export class PersonGateway {
  constructor(readonly id: number, public lastName: string, public deps: number) {}

  static async find(db: Pool, id: number): Promise<PersonGateway | null> {
    const { rows } = await db.query<{ id: number; last_name: string; deps: number }>(
      'SELECT id, last_name, deps FROM people WHERE id = $1', [id]);
    return rows[0] ? new PersonGateway(rows[0].id, rows[0].last_name, rows[0].deps) : null;
  }
  async update(db: Pool): Promise<void> {
    await db.query('UPDATE people SET last_name = $2, deps = $3 WHERE id = $1', [this.id, this.lastName, this.deps]);
  }
}
